// skate1 - XDK graphics library call tracing
//
// With d3d_trace_start_seconds > 0, from that many seconds after launch the
// hooks generated by tools/gen_d3d_trace.py count, over d3d_trace_frames
// frames (D3DDevice_Swap calls), how often each library entry point is called
// from outside the library (outer) and from inside it (nested), from which
// call sites and on which thread, and record the outer calls of one frame in
// order with their first arguments. The result goes to d3d_trace_path.

#include "d3d_trace.h"

#include <pthread.h>

#include <array>
#include <atomic>
#include <chrono>
#include <cstdio>
#include <mutex>
#include <string>
#include <vector>

#include <rex/cvar.h>
#include <rex/logging.h>

REXCVAR_DEFINE_INT32(d3d_trace_start_seconds, 0, "Skate1",
                     "Seconds after launch to start tracing XDK graphics library calls (0 = off)")
    .range(0, 3600);
REXCVAR_DEFINE_INT32(d3d_trace_frames, 120, "Skate1", "Frames to trace graphics library calls over")
    .range(1, 100000);
REXCVAR_DEFINE_STRING(d3d_trace_path, "d3d_trace.txt", "Skate1",
                      "File the graphics library call trace is written to");

namespace {

constexpr uint32_t kMaxFunctions = 1024;
constexpr uint32_t kMaxCallSites = 6;
constexpr size_t kMaxSequence = 40000;

struct FunctionStats {
  std::atomic<uint64_t> outer{0};
  std::atomic<uint64_t> nested{0};
  std::array<std::atomic<uint32_t>, kMaxCallSites> call_sites{};
  std::atomic<uint64_t> thread_tag{0};
  char thread_name[16] = {};
};

struct SequenceEntry {
  uint32_t index;
  uint32_t call_site;
  uint32_t r3, r4, r5, r6;
};

FunctionStats g_stats[kMaxFunctions];
// 0 = waiting, 1 = tracing, 2 = done.
std::atomic<int> g_state{0};
std::atomic<int> g_frames{0};
std::atomic<bool> g_sequence_recording{false};
std::mutex g_sequence_mutex;
std::vector<SequenceEntry> g_sequence;
const auto g_launch = std::chrono::steady_clock::now();
thread_local int t_depth = 0;

void RecordCallSite(FunctionStats& stats, uint32_t call_site) {
  for (auto& slot : stats.call_sites) {
    uint32_t value = slot.load(std::memory_order_relaxed);
    if (value == call_site) {
      return;
    }
    if (!value && slot.compare_exchange_strong(value, call_site)) {
      return;
    }
    if (value == call_site) {
      return;
    }
  }
}

void Dump() {
  std::string path = REXCVAR_GET(d3d_trace_path);
  FILE* file = std::fopen(path.c_str(), "w");
  if (!file) {
    REXLOG_ERROR("d3d trace: cannot write {}", path);
    return;
  }
  int frames = std::max(g_frames.load(), 1);
  std::fprintf(file, "# frames %d\n# address outer_per_frame nested_per_frame thread call_sites\n",
               frames);
  for (uint32_t i = 0; i < kD3DTraceCount; ++i) {
    FunctionStats& stats = g_stats[i];
    uint64_t outer = stats.outer.load(), nested = stats.nested.load();
    if (!outer && !nested) {
      continue;
    }
    std::fprintf(file, "%08X %.2f %.2f %s", kD3DTraceAddresses[i], double(outer) / frames,
                 double(nested) / frames, stats.thread_name[0] ? stats.thread_name : "?");
    for (auto& slot : stats.call_sites) {
      if (uint32_t value = slot.load()) {
        std::fprintf(file, " %08X", value);
      }
    }
    std::fprintf(file, "\n");
  }
  std::fprintf(file, "# sequence of one frame: address call_site r3 r4 r5 r6\n");
  std::lock_guard<std::mutex> lock(g_sequence_mutex);
  for (const SequenceEntry& entry : g_sequence) {
    std::fprintf(file, "S %08X %08X %08X %08X %08X %08X\n", kD3DTraceAddresses[entry.index],
                 entry.call_site, entry.r3, entry.r4, entry.r5, entry.r6);
  }
  std::fclose(file);
  REXLOG_INFO("d3d trace: {} frames written to {}", frames, path);
}

void OnSwap() {
  int state = g_state.load(std::memory_order_acquire);
  if (state == 0) {
    int start = REXCVAR_GET(d3d_trace_start_seconds);
    if (start > 0 && std::chrono::steady_clock::now() - g_launch >= std::chrono::seconds(start)) {
      g_state.store(1, std::memory_order_release);
      g_sequence_recording.store(true, std::memory_order_release);
      REXLOG_INFO("d3d trace: started");
    }
    return;
  }
  if (state != 1) {
    return;
  }
  // The first traced frame's sequence is complete.
  g_sequence_recording.store(false, std::memory_order_release);
  if (g_frames.fetch_add(1) + 1 >= REXCVAR_GET(d3d_trace_frames)) {
    g_state.store(2, std::memory_order_release);
    Dump();
  }
}

}  // namespace

void D3DTraceEnter(uint32_t index, const PPCContext& ctx) {
  int depth = t_depth++;
  if (index == kD3DTraceSwapIndex && depth == 0) {
    OnSwap();
  }
  if (g_state.load(std::memory_order_relaxed) != 1) {
    return;
  }
  FunctionStats& stats = g_stats[index];
  if (depth) {
    stats.nested.fetch_add(1, std::memory_order_relaxed);
    return;
  }
  stats.outer.fetch_add(1, std::memory_order_relaxed);
  uint32_t call_site = uint32_t(ctx.lr) - 4;
  RecordCallSite(stats, call_site);
  uint64_t expected = 0;
  if (stats.thread_tag.compare_exchange_strong(expected, 1)) {
    pthread_getname_np(pthread_self(), stats.thread_name, sizeof(stats.thread_name));
  }
  if (g_sequence_recording.load(std::memory_order_relaxed)) {
    std::lock_guard<std::mutex> lock(g_sequence_mutex);
    if (g_sequence.size() < kMaxSequence) {
      g_sequence.push_back(
          {index, call_site, ctx.r3.u32, ctx.r4.u32, ctx.r5.u32, ctx.r6.u32});
    }
  }
}

void D3DTraceLeave(uint32_t index) {
  (void)index;
  --t_depth;
}
